/* Degree goals are independent of transcript records. Missing institutional rules stay explicitly missing. */
const degreeKinds=['Associate — transfer / DTA','Associate — science transfer / AS-T','Associate — career / applied','Bachelor’s degree','Second major (one bachelor’s award)','Concurrent second bachelor’s degree','Second bachelor’s degree after graduation','Second major / double degree','Certificate','Other credential'];
function degreeCoursePool(){const pool=new Map();for(const original of state.degreeCourses||[]){const c={...original,completed:false,grade:''};if(c.recordRef){const live=state.courses.find(r=>MultiDegree.key({...r,units:r.units||c.units})===c.recordRef&&E.passing(r));if(live){c.completed=true;c.grade=live.grade}}pool.set(MultiDegree.key(c),c)}for(const row of state.courses||[]){if(!E.passing(row)||(!row.units&&!row.imported))continue;const c={...row,units:row.units||'Quarter',completed:true,prereqs:[],coreqs:[]},key=MultiDegree.key(c),existing=pool.get(key);pool.set(key,{...existing,...c,prereqs:existing?.prereqs||[],coreqs:existing?.coreqs||[]})}return[...pool.values()]}

let degreeOptimizationCache={key:null,value:null};
function degreeActivePool(goals,pool){const map=new Map(pool.map(c=>[MultiDegree.key(c),c])),needed=new Set();function add(k){if(needed.has(k))return;needed.add(k);const c=map.get(k);for(const dep of [...(c?.prereqs||[]),...(c?.coreqs||[])])add(dep)}for(const g of goals)for(const r of g.requirements)r.choices.forEach(add);return [...needed].map(k=>map.get(k)).filter(Boolean)}
function degreeCalendar(pool=degreeActivePool(state.degreeGoals||[],degreeCoursePool())){const units=[...new Set(pool.map(c=>c.units||'Quarter'))],calendar=units.length===1?units[0]:state.profile?.calendar||'Quarter';return{...state.profile,calendar,startTerm:calendar==='Semester'&&(!state.profile?.startTerm||state.profile.startTerm==='Winter')?'Fall':state.profile?.startTerm||'Winter'}}
function degreeTermName(i){return ProductCore.termName(degreeOptimize().calendar||degreeCalendar(),i)}
function degreeOptimize(){const key=JSON.stringify([state.degreeGoals,state.degreeCourses,state.courses,state.degreePolicyMode,mode,state.profile]);if(degreeOptimizationCache.key===key)return degreeOptimizationCache.value;const goals=state.degreeGoals||[];const stale=(state.degreeCourses||[]).find(c=>c.recordRequirement&&c.recordRef&&c.recordRequirement!=='CSS 142'&&!AcademicPathway.requirements.some(r=>r.code===c.recordRequirement&&AcademicPathway.completion(r,AcademicPathway.records(state))));if(stale)return{status:'needs-review',errors:['An imported completed requirement has changed: '+stale.recordRequirement+'. Recheck and reimport the UWB subset before using its connected route.'],courses:[]};const pool=degreeActivePool(goals,degreeCoursePool()),calendar=degreeCalendar(pool),result={...MultiDegree.optimize(goals,pool,{mode:state.degreePolicyMode||'potential',creditCap:{Flexible:10,Balanced:15,Accelerated:20}[mode]||15,maxCourses:+state.profile?.maxCourses||99,season:i=>ProductCore.terms(calendar,i).season,nodeLimit:60000,timeLimitMs:180}),calendar};degreeOptimizationCache={key,value:result};return result}

function degreeIds(){return 'degree-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function degreeCoursesOptions(pool){return pool.map(c=>`<option value="${esc(MultiDegree.key(c))}">${esc(c.code)} · ${esc(c.institution)} · ${c.credits} ${esc(c.units||'Quarter')} credits${c.completed?' · completed':''}</option>`).join('')}
function degreeSummary(){const goals=state.degreeGoals||[];if(!goals.length)return '';const result=degreeOptimize();return `<div class="degree-summary"><div class="degree-merge-mark" aria-hidden="true"><i></i><i></i><b>↗</b></div><div><strong>${goals.length} degree goal${goals.length===1?'':'s'}, one connected plan.</strong><p>${result.usage?`${result.usage.filter(c=>c.shared).length} course${result.usage.filter(c=>c.shared).length===1?'':'s'} could serve more than one goal.`:'Add requirements to find shared classes.'} ${result.status==='conditional'?'Sharing still needs advisor confirmation.':''}</p></div><a class="journey-secondary" href="#degrees">See my combined route →</a></div>`}
function degreeGoalPanel(goal,pool,result){const assignments=result.assignments?.filter(a=>a.goalId===goal.id)||[];return `<article class="degree-goal"><span class="eyebrow">${esc(goal.kind)}</span><h2>${esc(goal.name)}</h2><label>Goal role<select data-degree-role="${esc(goal.id)}">${options(['concurrent','primary','backup'],goal.role||'concurrent')}</select></label>${goal.role==='backup'?'<p>Backup preparation checklist: enter early admission requirements, not an assumed second full degree.</p>':''}<p>${esc(goal.institution)} · ${esc(goal.catalogYear||'Catalog year not entered')}</p><span class="degree-evidence">${goal.preset?(goal.edited?'Source-based subset, modified by you — recheck edits':'Source-based checklist subset — not a full degree audit'):'Student/advisor-entered checklist — not independently verified'}</span>${goal.notes?.length?'<p class="plan-trust-alert">Additional placement, grade or course-combination checks need review.</p>':''}<p>${assignments.filter(a=>a.completed).length} completed course entries assigned to this goal. Final degree applicability still needs review.</p><details><summary>Requirements & sharing rules</summary><p>${goal.preset?'This is a source-based subset, not a full degree audit. See its program scope, unresolved rules and notes below.':'Add the college’s official requirements below. An empty checklist never means a degree is complete.'}</p>${ProductCore.safeURL(goal.source)?`<a class="journey-secondary" href="${esc(ProductCore.safeURL(goal.source))}" target="_blank" rel="noopener">Your program source ↗</a>`:''}${goal.notes?.length?`<ul>${goal.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}<div class="degree-requirement-list">${goal.requirements.map(r=>`<div><strong>${esc(r.label)}</strong><small>Choose at least ${r.count||1}${r.minCredits?' · minimum '+r.minCredits+' '+r.creditUnits+' credits':''} · ${r.choices.map(k=>pool.find(c=>MultiDegree.key(c)===k)?.code||'Missing course').map(esc).join(' / ')}${r.minGrade!=null?' · minimum grade '+r.minGrade:''}</small>${r.choices.length>1&&(r.count||1)===1&&!r.minCredits?`<label>Teaching school / course alternative<select data-lock-alternative="${esc(r.id)}" data-goal="${esc(goal.id)}"><option value="">Optimize across documented alternatives</option>${r.choices.map(k=>{const c=pool.find(c=>MultiDegree.key(c)===k);return c?`<option value="${esc(k)}" ${r.lockedChoice===k?'selected':''}>${esc(c.institution)} · ${esc(c.code)}</option>`:''}).join('')}</select></label>`:''}<button class="journey-secondary" data-remove-degree-requirement="${esc(goal.id)}" data-requirement-id="${esc(r.id)}">Remove requirement</button></div>`).join('')||'<p>No requirements entered yet.</p>'}</div><form data-degree-sharing="${esc(goal.id)}"><label>Exact catalog year<input name="catalogYear" value="${esc(goal.catalogYear)}" maxlength="30"></label><label>Can a course also count toward another degree?<select name="sharing">${options(['review','allowed','exclusive'],goal.sharing||'review')}</select></label><p class="quiet-note">review = unconfirmed; allowed = advisor confirmed by you; exclusive = do not share across goals.</p><label>Official sharing policy URL<input name="sharingSource" type="url" value="${esc(goal.sharingSource)}" placeholder="https://"></label><label><input name="advisorConfirmed" type="checkbox" ${goal.advisorConfirmed?'checked':''}> My advisor confirmed this policy for these degrees and catalog years.</label><button class="btn">Save sharing rules</button></form></details><button class="journey-secondary" data-remove-degree="${esc(goal.id)}">Remove this goal</button></article>`}
function degreeCheckpointPanel(result){const goals=state.degreeGoals||[],point=MultiDegree.checkpoint(result,goals);if(!goals.some(g=>g.role==='backup'))return '';return `<aside class="degree-checkpoint"><span class="eyebrow">YOUR DECISION CHECKPOINT</span><h3>${point?'First dedicated '+(result.calendar?.calendar==='Semester'?'semester':'quarter')+': '+esc(degreeTermName(point.term)):'No fully primary-only term identified'}</h3><p>${point?'Every scheduled class in this term is assigned exclusively to your primary goal in the entered checklists.':'Shared, backup, concurrent or unassigned prerequisite classes keep the draft from identifying a dedicated term.'} This is a planning checkpoint, not an irreversible commitment. Incomplete checklists can change it.</p>${point?.backupPending?'<p>Backup preparation is still scheduled at or after this checkpoint. Review timing before committing.</p>':''}<p>Backup preparation is prioritized among available classes; prerequisites, sequences, workload and offerings still apply.</p></aside>`}
function degreeRoutePanel(result){if(!result.usage)return `<div class="degree-route-empty"><h3>${result.status==='needs-requirements'?'Add your requirements first.':'A route needs more information.'}</h3><ul>${(result.errors||[]).map(e=>`<li>${esc(e)}</li>`).join('')}</ul><p>No degree-completion claim is made from an incomplete checklist.</p></div>`;const shared=result.usage.filter(c=>c.shared);return `<div class="degree-route-header"><div><span class="eyebrow">${result.status==='conditional'?'CONDITIONAL SHARING DRAFT':'ENTERED-REQUIREMENT DRAFT'}</span><h2>One class. More doors open.</h2><p>${esc(result.method)}${result.optimal?'':' · Search stopped at its limit.'}</p></div><div class="degree-metrics"><strong>${result.plannedCount}</strong><span>unique future course entries</span></div></div><div class="degree-route-stats"><span>${shared.length} potential cross-degree course${shared.length===1?'':'s'}</span>${Object.entries(result.totals).map(([units,n])=>`<span>${n} new ${esc(units.toLowerCase())} credits counted once</span>`).join('')}${result.avoidedDuplicateCredits?`<span>${result.avoidedDuplicateCredits} credits not repeated in this entered draft</span>`:''}</div>${result.status==='conditional'?'<p class="plan-trust-alert" role="alert">Potential overlap only. Unknown sharing policies are not permission to count a class toward two awards. Confirm with both institutions.</p>':''}${result.mixedUnits?'<p class="plan-trust-alert">Quarter and semester credits are not converted or summed. This is a course-selection proposal; a combined term schedule requires institutional review.</p>':''}${degreeCheckpointPanel(result)}${advisingCheckpoints()}<div class="degree-route">${result.usage.map((c,i)=>`<article class="degree-route-step ${c.shared?'shared-step':''}" style="--route-index:${i}"><div class="degree-step-number">${String(i+1).padStart(2,'0')}</div><div><span class="eyebrow">${c.completed&&!result.courses.some(p=>MultiDegree.key(p)===c.key)?'ALREADY IN YOUR RECORD':result.courses.find(p=>MultiDegree.key(p)===c.key)?.term!=null?esc(degreeTermName(result.courses.find(p=>MultiDegree.key(p)===c.key).term)):'FUTURE COURSE'}</span><h3>${esc(c.code)} <small>${esc(c.title)}</small></h3><p>${esc(c.institution)} · ${c.credits} ${esc((c.units||'Quarter').toLowerCase())} credits</p><div class="degree-benefits">${c.assignments.map(a=>`<span>${esc(a.goal)}<small>${esc(a.requirement)}</small></span>`).join('')||'<span>Supports an entered prerequisite or co-requisite.</span>'}</div>${c.shared?`<p class="sharing-status">${c.sharingConfirmed?'Sharing marked advisor-confirmed by you; final audits still required.':'Potential sharing — policy review needed.'}</p>`:''}</div></article>`).join('')}</div><details class="journey-footnote"><summary>What “efficient” means here</summary><p>The bounded search allocates entered course alternatives to entered requirement slots, adds dependencies, and minimizes new credits (or course count when credit systems differ). Credits are counted once per distinct institution/course/credit-unit record. It does not infer equivalencies from similar titles, certify an entire degree, establish residency/total-credit compliance or guarantee the fastest graduation date. Draft terms respect entered prerequisites, co-requisites, seasonal rules and workload. Missing catalogs and policies need college review.</p></details><div class="actions"><button class="btn" id="export-degree-route">Download combined plan data ↓</button><button class="btn" id="export-degree-image" ${result.mixedUnits||!result.courses.length?'disabled':''}>Download route image ↓</button></div>`}
function degreePlanner(){const goals=state.degreeGoals||[],pool=degreeCoursePool(),result=degreeOptimize();return journeyPage(3,'More than one goal. One smarter route.',`<a class="journey-secondary" href="#programs">Browse official programs · choose a primary or backup →</a><p class="journey-lede">Connect an associate degree, bachelor’s degree or another credential. Find shared classes without counting credits twice.</p><div class="degree-goals">${goals.map(g=>degreeGoalPanel(g,pool,result)).join('')}</div><section class="degree-optimizer"><div class="row"><h2>Your connected route</h2><button class="btn primary" id="optimize-degrees">Find Shared Classes ↗</button></div><label>Sharing analysis<select id="degree-policy-mode">${options(['potential','confirmed'],state.degreePolicyMode||'potential')}</select></label><p class="quiet-note">Potential finds overlaps needing policy review. Confirmed only allows cross-degree sharing you marked advisor-confirmed with a policy link and catalog year.</p><div id="degree-route-result" aria-live="polite">${degreeRoutePanel(result)}</div></section><details class="journey-advanced" ${goals.length?'':'open'}><summary>Add a degree goal</summary><form id="degree-goal-form" class="form-grid"><div><label for="degree-name">Exact degree/program name</label><input id="degree-name" name="name" required maxlength="150" placeholder="Use your college’s exact program name"></div><div><label for="degree-kind">Type of goal</label><select id="degree-kind" name="kind" required><option value="">Choose the degree type</option>${options(degreeKinds)}</select></div><div><label for="degree-institution">Awarding college</label><input id="degree-institution" name="institution" list="degree-schools" required maxlength="120" value="${esc(state.profile?.degreeInstitution||state.profile?.institution)}"></div><div><label for="degree-year">Catalog year</label><input id="degree-year" name="catalogYear" maxlength="30" placeholder="e.g. 2026–27"></div><div><label for="degree-source">Official degree checklist URL</label><input id="degree-source" name="source" type="url" placeholder="https://"></div><button class="btn">Add Goal</button></form><p class="quiet-note">No full associate-degree catalog is loaded; this optimizes the requirements you enter, not an entire unaudited degree. Add requirements from the college/advisor. A DTA, AS-T or applied associate degree can have different transfer rules.</p><button class="btn" id="import-uwb-goal">Add supported UWB EE foundation/core subset</button><a class="journey-secondary" target="_blank" rel="noopener" href="https://www.sbctc.edu/colleges-staff/programs-services/transfer/direct-transfer-agreement.aspx">Official Washington DTA explanation ↗</a></details><details class="journey-advanced"><summary>Add course alternatives</summary><form id="degree-course-form" class="form-grid"><div><label for="dc-code">Official course code</label><input id="dc-code" name="code" required maxlength="50"></div><div><label for="dc-title">Title</label><input id="dc-title" name="title" required maxlength="150"></div><div><label for="dc-college">Teaching college</label><input id="dc-college" name="institution" required list="degree-schools" maxlength="120"></div><div><label for="dc-credits">Credits</label><input id="dc-credits" name="credits" type="number" min="0.5" max="30" step="0.5" required></div><div><label for="dc-units">Credit units</label><select id="dc-units" name="units">${options(['Quarter','Semester'])}</select></div><label><input name="foundation" type="checkbox"> Foundational course — prioritize when prerequisites allow</label><div><label for="dc-source">Official course source</label><input id="dc-source" name="source" type="url" placeholder="https://"></div><div><label for="dc-prereqs">Earlier required classes (optional)</label><select id="dc-prereqs" name="prereqs" multiple>${degreeCoursesOptions(pool)}</select></div><label>Same-term required classes (optional)<select name="coreqs" multiple>${degreeCoursesOptions(pool)}</select></label><button class="btn">Add Course Alternative</button></form><h3>Saved course alternatives</h3><div class="degree-course-pool">${(state.degreeCourses||[]).map(c=>`<div><strong>${esc(c.code)} · ${esc(c.institution)}</strong><label>Credits<input data-degree-credits="${esc(MultiDegree.key(c))}" type="number" value="${c.credits}" min="0.5" max="30" step="0.5"></label><button class="journey-secondary" data-remove-degree-course="${esc(MultiDegree.key(c))}">Remove alternative</button></div>`).join('')}</div><p class="quiet-note">Completed records are included automatically. Course alternatives are planning entries, not earned credit or inferred equivalencies.</p></details><details class="journey-advanced"><summary>Add a degree requirement</summary><form id="degree-requirement-form"><div class="form-grid"><div><label for="dr-goal">Degree goal</label><select id="dr-goal" name="goalId" required>${goals.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></div><div><label for="dr-label">Requirement name</label><input id="dr-label" name="label" required maxlength="150" placeholder="Copy the college’s requirement label"></div><label>Requirement stage<select name="phase"><option value="degree">Degree requirement</option><option value="foundation">Foundation</option><option value="admission">Major admission prerequisite</option></select></label><div><label for="dr-count">Number of distinct courses needed</label><input id="dr-count" type="number" name="count" min="1" max="8" value="1" required></div><div><label for="dr-mincredits">Minimum credits in this category (optional)</label><input id="dr-mincredits" name="minCredits" type="number" min="0.5" max="120" step="0.5"></div><div><label for="dr-creditunits">Units for that credit minimum</label><select id="dr-creditunits" name="creditUnits">${options(['Quarter','Semester'])}</select></div><div><label for="dr-grade">Published minimum grade (optional, numeric 0–4)</label><input id="dr-grade" type="number" name="minGrade" min="0" max="4" step="0.1"></div><div><label for="dr-source">Official requirement source</label><input id="dr-source" name="source" type="url" placeholder="https://"></div></div><fieldset class="degree-course-choices"><legend>Which courses are documented alternatives?</legend>${pool.map(c=>`<label><input name="choice" type="checkbox" value="${esc(MultiDegree.key(c))}"> ${esc(c.code)} · ${esc(c.institution)} · ${c.credits} ${esc((c.units||'Quarter').toLowerCase())} credits</label>`).join('')||'<p>Add course alternatives first.</p>'}</fieldset><details><summary>Sharing within this same degree</summary><label><input name="allowWithin" type="checkbox"> College policy permits overlap with another requirement in this degree.</label><label>Official within-degree sharing policy<input name="sharingSource" type="url" placeholder="https://"></label><p class="quiet-note">By default one class fills only one requirement within a degree. Both requirements need permission and source links to share it.</p></details><button class="btn">Add Requirement</button></form></details><datalist id="degree-schools">${schools.map(s=>`<option value="${esc(s)}">`).join('')}</datalist><p class="quiet-note">Older manual records without confirmed credit units are excluded from this combined search until updated in your academic record. <a href="#history" class="journey-secondary">Review credit units →</a></p><p class="quiet-note">Shared courses are not automatic permission for multiple awards. Minimum totals, residency, catalog years, transfer acceptance and each institution’s double-counting policies require official review.</p>`,'roadmap')}
function importUWBGoal(){
 if((state.degreeGoals||[]).some(g=>g.preset==='uwb-ee'))return toast('That UWB subset is already added. Edit or remove the goal to import it again.');
 const draft={...state,profile:{...state.profile,target:AcademicPathway.UWB,major:'Electrical Engineering',calendar:'Quarter'}},plan=AcademicPathway.plan(draft,mode),records=AcademicPathway.records(state),entries=new Map();
 for(const req of AcademicPathway.requirements){const resolved=plan.remaining.find(c=>c.code===req.code)||req,earned=AcademicPathway.completion(req,records)||(req.code==='CSS 142'&&plan.done.includes(req.code)?records.find(c=>c.institution===AcademicPathway.BC&&c.code==='CS 210'&&E.passing(c)):null);let c;if(earned)c={code:earned.code,title:earned.title||req.title,institution:earned.institution,credits:Number(earned.transcriptCredits??earned.credits),units:'Quarter',recordRef:MultiDegree.key({...earned,units:'Quarter'}),recordRequirement:req.code,source:req.source,completed:false};else c={code:resolved.displayCode||resolved.defaultDisplay||resolved.code,title:resolved.title,institution:resolved.institution,credits:resolved.credits,units:'Quarter',source:resolved.source,completed:false};entries.set(req.code,{req,resolved,course:c});}
 for(const [code,entry]of entries){entry.course.prereqs=(entry.resolved.prereqs||[]).map(k=>entries.has(k)?MultiDegree.key(entries.get(k).course):'missing|'+k);entry.course.coreqs=(entry.resolved.coreqs||[]).map(k=>entries.has(k)?MultiDegree.key(entries.get(k).course):'missing|'+k);if(entry.req.seasons)entry.course.seasons=entry.req.seasons;entry.course.priority=AcademicPathway.requirements.length-[...entries.keys()].indexOf(code);}
 for(const {req,resolved}of entries.values())if(resolved.institution===AcademicPathway.UWB)for(const [pre,minimum]of Object.entries(req.prereqMin||{})){const entry=entries.get(pre);if(entry)entry.pathMinGrade=Math.max(entry.pathMinGrade||entry.req.minGrade||2,minimum);}
 const pool=new Map((state.degreeCourses||[]).map(c=>[MultiDegree.key(c),c]));for(const {course:c}of entries.values()){const old=pool.get(MultiDegree.key(c));if(old&&Number(old.credits)!==Number(c.credits))return toast('Credit mismatch for '+c.code+'. Review the existing alternative before importing.');pool.set(MultiDegree.key(c),{...old,...c})}
 const goal={id:degreeIds(),name:'UWB Electrical Engineering — foundation/core subset',kind:'Bachelor’s degree',institution:AcademicPathway.UWB,catalogYear:'Confirm your catalog year',source:AcademicPathway.sources.curriculum,sharing:'review',advisorConfirmed:false,preset:'uwb-ee',notes:[...new Set([plan.readiness,...(plan.warnings||[]),...AcademicPathway.requirements.map(r=>r.review),'Source-college enrollment rules, laboratory combinations, placement and future offerings require institutional confirmation.'].filter(Boolean))],requirements:[...entries.values()].map(({req,course,pathMinGrade})=>({id:req.code,phase:req.admissionMin?'admission':'degree',label:req.title+(pathMinGrade?' (grade needed for a later prerequisite)':''),count:1,choices:[MultiDegree.key(course)],minGrade:Math.max(pathMinGrade||0,req.minGrade||2,req.admissionMin||0),source:req.admissionMin?AcademicPathway.sources.admissions:pathMinGrade?AcademicPathway.sources.css:req.source,evidence:'Existing source-checked UWB requirement subset'}))};state.degreeGoals||=[];if(state.degreeGoals.length>=6)return toast('Use up to six degree goals.');state.degreeCourses=[...pool.values()];state.degreeGoals.push(goal);save();render();toast('UWB foundation/core subset added. It is not a complete degree audit.')
}
function bindDegrees(){
 document.querySelectorAll('[data-degree-role]').forEach(el=>el.onchange=()=>{const goal=state.degreeGoals.find(g=>g.id===el.dataset.degreeRole);if(el.value!=='concurrent'&&state.degreeGoals.some(g=>g.id!==goal.id&&g.role===el.value)){el.value=goal.role||'concurrent';return toast('Use one primary and one backup goal; other goals can run concurrently.')}goal.role=el.value;save();render()});
 document.querySelector('#journey-setup')?.addEventListener('submit',e=>{const f=Object.fromEntries(new FormData(e.target));if(!f.credential)return;e.preventDefault();e.stopImmediatePropagation();const prior=state.profile||{};state.profile={...prior,grade:f.grade,major:f.major||prior.major||'',target:f.target||prior.target||'',credential:f.credential,load:prior.load||'Balanced',startYear:prior.startYear||2027,startTerm:prior.startTerm||'Winter'};state.historyDone=true;mode=state.profile.load;save();location.hash='degrees';render()},{capture:true});
 document.querySelectorAll('[data-associate-college]').forEach(el=>el.onclick=()=>{state.profile={...state.profile,credential:'Associate degree',degreeInstitution:el.dataset.associateCollege};save();location.hash='degrees';render()});

 document.querySelectorAll('[data-degree-credits]').forEach(el=>el.onchange=()=>{const n=+el.value;if(!Number.isFinite(n)||n<=0||n>30)return toast('Enter credits between 0 and 30.');const c=state.degreeCourses.find(c=>MultiDegree.key(c)===el.dataset.degreeCredits);c.credits=n;c.evidence='Student-edited credit amount; confirm with college';for(const g of state.degreeGoals||[])if(g.preset&&g.requirements.some(r=>r.choices.includes(MultiDegree.key(c))))g.edited=true;save();render()});
 document.querySelectorAll('[data-remove-degree-course]').forEach(el=>el.onclick=()=>{const key=el.dataset.removeDegreeCourse;if((state.degreeGoals||[]).some(g=>g.requirements.some(r=>r.choices.includes(key))))return toast('This alternative is used by a requirement. Update that requirement before removing the course.');if(!confirm('Remove this planning alternative? Academic records are unchanged.'))return;state.degreeCourses=state.degreeCourses.filter(c=>MultiDegree.key(c)!==key);save();render()});

 document.querySelector('#degree-goal-form')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.source&&!ProductCore.safeURL(f.source))return toast('Use an HTTPS official program source.');state.degreeGoals||=[];if(state.degreeGoals.length>=6)return toast('Use up to six degree goals.');state.degreeGoals.push({...f,id:degreeIds(),role:state.degreeGoals.length?'concurrent':'primary',sharing:'review',advisorConfirmed:false,requirements:[]});save();render()});
 document.querySelector('#degree-course-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target),f=Object.fromEntries(form),c={...f,code:f.code.trim().toUpperCase(),title:f.title.trim(),institution:f.institution.trim(),credits:+f.credits,foundation:form.has('foundation'),prereqs:form.getAll('prereqs'),coreqs:form.getAll('coreqs'),completed:false,evidence:'user-entered'};if(c.source&&!ProductCore.safeURL(c.source))return toast('Use an HTTPS course source.');if(degreeCoursePool().some(old=>MultiDegree.key(old)===MultiDegree.key(c)))return toast('That institution/course/unit alternative is already in the pool.');const errors=MultiDegree.validate(state.degreeGoals||[],[...(state.degreeCourses||[]),c]);if(errors.length)return toast(errors[0]);state.degreeCourses||=[];state.degreeCourses.push(c);save();render()});
 document.querySelector('#degree-requirement-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target),f=Object.fromEntries(form),goal=state.degreeGoals?.find(g=>g.id===f.goalId);if(!goal)return toast('Add a degree goal first.');const choices=form.getAll('choice');if(!choices.length)return toast('Select at least one documented course alternative.');if(f.source&&!ProductCore.safeURL(f.source))return toast('Use an HTTPS requirement source.');const allowWithin=e.target.elements.namedItem('allowWithin').checked;if(allowWithin&&!ProductCore.safeURL(f.sharingSource))return toast('Add the official within-degree sharing policy first.');const req={id:degreeIds(),label:f.label.trim(),phase:f.phase||'degree',count:+f.count,choices,minCredits:f.minCredits===''?null:+f.minCredits,creditUnits:f.creditUnits,minGrade:f.minGrade===''?null:+f.minGrade,source:f.source,evidence:'student/advisor-entered; not independently verified',allowWithin,sharingSource:f.sharingSource};const candidate=state.degreeGoals.map(g=>g===goal?{...g,requirements:[...g.requirements,req]}:g),errors=MultiDegree.validate(candidate,degreeActivePool(candidate,degreeCoursePool()));if(errors.length)return toast(errors[0]);goal.requirements.push(req);if(goal.preset)goal.edited=true;save();render()});
 document.querySelector('#degree-policy-mode')?.addEventListener('change',e=>{state.degreePolicyMode=e.target.value;save();render()});
 document.querySelectorAll('[data-degree-sharing]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form)),goal=state.degreeGoals.find(g=>g.id===form.dataset.degreeSharing),confirmed=form.elements.namedItem('advisorConfirmed').checked;if(f.sharing==='allowed'&&(!confirmed||!ProductCore.safeURL(f.sharingSource)||!/(?:19|20)\d{2}/.test(f.catalogYear||'')))return toast('Allowed sharing needs your advisor confirmation, an HTTPS policy link and an exact catalog year. Enter the exact catalog year in this form.');goal.catalogYear=f.catalogYear;goal.sharing=f.sharing;goal.sharingSource=f.sharingSource;goal.advisorConfirmed=confirmed;save();render()}));
 document.querySelectorAll('[data-remove-degree]').forEach(el=>el.onclick=()=>{if(!confirm('Remove this degree goal and its entered requirements? Your academic record and course alternatives stay saved.'))return;state.degreeGoals=state.degreeGoals.filter(g=>g.id!==el.dataset.removeDegree);save();render()});
 document.querySelectorAll('[data-remove-degree-requirement]').forEach(el=>el.onclick=()=>{const g=state.degreeGoals.find(g=>g.id===el.dataset.removeDegreeRequirement);if(!confirm('Remove this requirement from the planning checklist?'))return;g.requirements=g.requirements.filter(r=>r.id!==el.dataset.requirementId);if(g.preset)g.edited=true;save();render()});
 document.querySelector('#import-uwb-goal')?.addEventListener('click',importUWBGoal);
 document.querySelector('#optimize-degrees')?.addEventListener('click',()=>{const el=document.querySelector('#degree-route-result');el.innerHTML=degreeRoutePanel(degreeOptimize());el.scrollIntoView({behavior:journeyReduced()?'instant':'smooth',block:'start'});document.querySelector('#export-degree-route')?.addEventListener('click',exportDegreeRoute);document.querySelector('#export-degree-image')?.addEventListener('click',exportDegreeImage)});
 document.querySelector('#export-degree-route')?.addEventListener('click',exportDegreeRoute);document.querySelector('#export-degree-image')?.addEventListener('click',exportDegreeImage);
 document.querySelectorAll('[data-record-units]').forEach(el=>el.onchange=()=>{state.courses[+el.dataset.recordUnits].units=el.value;save();render()});
 document.querySelectorAll('[data-degree-catalog]').forEach(el=>el.onchange=()=>{state.degreeGoals.find(g=>g.id===el.dataset.degreeCatalog).catalogYear=el.value;save();render()});
}
function exportDegreeImage(){const r=degreeOptimize();if(r.mixedUnits||!r.courses?.length)return toast('Image export needs a single credit system and future courses. Use the data export for this route.');downloadPlanImage({courses:r.courses,profile:{...degreeCalendar(),major:'Connected degree plan',target:(state.degreeGoals||[]).length+' goals · Unofficial entered-requirement draft',exportNote:r.status==='conditional'?'Potential sharing only. Confirm sharing policies, requirements and registration with both colleges.':'Advisor-confirmed by you. Final degree audits and registration still need institutional review.'}})}
function exportDegreeRoute(){download('camino-connected-degrees.json',JSON.stringify({status:'Unofficial entered-requirement allocation; sharing and degree audits need institutional confirmation',goals:state.degreeGoals,route:degreeOptimize()},null,2))}
function installDegrees(){
 const simpleProfile=profile;profile=()=>simpleProfile().replace('<button class="btn primary">Show My Next Step →</button>',`<details class="setup-college"><summary>Associate degree or more than one credential?</summary><label for="j-credential">What do you want to work toward?</label><select id="j-credential" name="credential"><option value="">Keep exploring one direction</option>${options(['Associate degree','Bachelor’s degree','Several degrees or credentials','Certificate'],state.profile?.credential)}</select></details><button class="btn primary">Show My Next Step →</button>`)+`<section class="page degree-entry"><details class="journey-advanced"><summary>Working toward an associate degree or more than one credential?</summary><p>Add your degree goals and the college’s requirements. Look for one class that can support more than one goal.</p><a class="btn" href="#degrees">Connect My Degree Goals →</a></details></section>`;
 const simplePlan=roadmap;roadmap=()=>{const goals=state.degreeGoals||[],r=goals.length?degreeOptimize():null;if(r?.usage){return journeyPage(3,'Your degree goals, connected.',`<p class="journey-lede">${goals.length} goals. One set of classes to review.</p><section class="next-action"><div><span class="eyebrow">YOUR NEXT STEP</span><h2>${r.status==='conditional'?'Confirm your shared-course options.':'Review your connected classes.'}</h2><p>${r.plannedCount} unique future course entries. Credits are counted once in this draft.</p></div><a class="btn primary" href="#degrees">See My Combined Route →</a></section>${degreeSummary()}<div class="connected-next">${r.usage.filter(c=>r.courses.some(p=>MultiDegree.key(p)===c.key)).slice(0,3).map(c=>`<article><span class="eyebrow">${c.shared?'ONE CLASS / MULTIPLE GOALS':'NEXT COURSE ENTRY'}</span><h3>${esc(c.code)}</h3><p>${esc(c.title)}</p><small>${[...new Set(c.assignments.map(a=>a.goal))].map(esc).join(' + ')}</small></article>`).join('')}</div><p class="quiet-note">This covers entered requirements only. Each degree’s full audit, residency rules and sharing policies still need college confirmation.</p><details class="journey-advanced"><summary>My original single-program plan & tools</summary>${simplePlan()}</details>`,'results')}return simplePlan()+`<section class="page degree-entry">${degreeSummary()}<details class="journey-advanced"><summary>Associate degrees, multiple degrees & shared classes</summary><p>Plan several credentials together. Sharing and transfer policies must be confirmed with the awarding colleges.</p><a class="btn" href="#degrees">Plan Connected Degrees →</a></details></section>`};
 const oldStatus=recordStatusControls;recordStatusControls=()=>oldStatus()+`<section class="card"><h3>Credit units for connected-degree planning</h3><p>Confirm the units on older manually entered records. Quarter and semester credits are not converted automatically.</p>${state.courses.map((c,i)=>`<label>${esc(c.code)} · ${esc(c.institution)}<select data-record-units="${i}"><option value="">Confirm credit units</option>${options(['Quarter','Semester'],c.units||(c.imported?'Quarter':''))}</select></label>`).join('')}</section>`;
 const originalBind=bind;bind=()=>{originalBind();bindDegrees()};
}
